import{_ as a,o,c as r,ag as n}from"./chunks/framework.44aEvdQQ.js";const g=JSON.parse('{"title":"Your role in VERA","description":"","frontmatter":{},"headers":[],"relativePath":"guide/roles.md","filePath":"guide/roles.md"}'),i={name:"guide/roles.md"};function t(l,e,s,d,u,c){return o(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="your-role-in-vera" tabindex="-1">Your role in VERA <a class="header-anchor" href="#your-role-in-vera" aria-label="Permalink to &quot;Your role in VERA&quot;">​</a></h1><p>Everyone using VERA has one of three roles. Your role determines what you can see and what you can do.</p><hr><h2 id="team-member" tabindex="-1">Team member <a class="header-anchor" href="#team-member" aria-label="Permalink to &quot;Team member&quot;">​</a></h2><p>The default role for anyone added to VERA.</p><p><strong>You can:</strong></p><ul><li>Log your own hours</li><li>Check your own time entries and weekly totals</li><li>See which projects you&#39;re working on and how many hours remain in your plan</li><li>Request time off</li><li>View your own approved and pending time-off requests</li></ul><p><strong>You can&#39;t see:</strong></p><ul><li>Other people&#39;s time entries</li><li>Financial figures (costs, revenue, margin)</li><li>Project deadlines</li><li>Your team&#39;s capacity or availability</li></ul><hr><h2 id="manager" tabindex="-1">Manager <a class="header-anchor" href="#manager" aria-label="Permalink to &quot;Manager&quot;">​</a></h2><p>Managers are typically project leads or account managers. A manager is usually assigned to one or more projects and sees data for those projects.</p><p><strong>In addition to everything a team member can do, you can:</strong></p><ul><li>See time logged by anyone on your assigned projects</li><li>See project health and burn rates (as percentages — not dollar values)</li><li>Approve or decline time-off requests</li><li>Log hours on behalf of team members (e.g. sick days, leave)</li><li>See project deadlines for your projects</li><li>See who&#39;s allocated to your projects and their remaining hours</li></ul><p><strong>You can&#39;t see:</strong></p><ul><li>Financial figures (costs, revenue, margin)</li><li>Projects you&#39;re not assigned to manage</li></ul><hr><h2 id="owner" tabindex="-1">Owner <a class="header-anchor" href="#owner" aria-label="Permalink to &quot;Owner&quot;">​</a></h2><p>Owners have full visibility across everything.</p><p><strong>In addition to everything a manager can do, you can:</strong></p><ul><li>See all projects, not just assigned ones</li><li>See all financial data: costs, revenue, margins, billing rates</li><li>See and manage rate history for the team</li><li>Create and cancel vendor liabilities</li><li>Add and remove team members</li><li>Set project budgets, deadlines, and billing rates</li><li>See the full reporting dashboard including P&amp;L</li></ul><hr><h2 id="how-roles-are-assigned" tabindex="-1">How roles are assigned <a class="header-anchor" href="#how-roles-are-assigned" aria-label="Permalink to &quot;How roles are assigned&quot;">​</a></h2><p>Roles are set by an owner. If you believe your role is wrong — for example, you&#39;re managing projects but can&#39;t see the right data — ask whoever administers VERA to update your access.</p><hr><h2 id="a-note-on-financial-data" tabindex="-1">A note on financial data <a class="header-anchor" href="#a-note-on-financial-data" aria-label="Permalink to &quot;A note on financial data&quot;">​</a></h2><p>Dollar figures are visible to owners only, by design. Managers see percentages — &quot;this project is at 73% of its budget&quot; — but not the underlying cost or contract value. This is intentional: financial context without the full picture can create more confusion than clarity.</p>',27)])])}const m=a(i,[["render",t]]);export{g as __pageData,m as default};
